xm12 N008 vm N009 0 sky130_fd_pr__nfet_01v8 w={W_xm12} l={L_xm12}
xm14 N009 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm14} l={L_xm14}
xm15 N009 VCMFB1 0 0 sky130_fd_pr__nfet_01v8 w={W_xm15} l={L_xm15}
